const raw = $input.first()?.json ?? {};
const input = raw.body && typeof raw.body === 'object' ? raw.body : raw;
const uuid = /^[0-9a-f]{8}-[0-9a-f]{4}-[1-5][0-9a-f]{3}-[89ab][0-9a-f]{3}-[0-9a-f]{12}$/i;
const organizationId = uuid.test(String(input.organization_id ?? '')) ? String(input.organization_id) : '';
const userId = uuid.test(String(input.requested_by_user_id ?? '')) ? String(input.requested_by_user_id) : '';
const processId = uuid.test(String(input.process_id ?? '')) ? String(input.process_id) : '';
return [{ json: { workflow_code: 'WF-019', source_code: 'SECOP_PIPELINE_ORCHESTRATION', orchestration_version: 2, orchestration_method: 'sequential_v2', lock_minutes: 60, stale_lock_minutes: 90, organization_id: organizationId, requested_by_user_id: userId, process_id: processId, processing_mode: String(input.processing_mode ?? 'all'), frontend_triggered: Boolean(organizationId), n8n_execution_id: String($execution.id ?? ''), trigger_type: String($execution.mode ?? 'manual'), configured_at: new Date().toISOString() } }];

