parameters.jsCode:
const input =
  $input.first()?.json ?? {};

const rawLockValue =
  input.lock_acquired;

const lockAcquired =
  rawLockValue === true
  || rawLockValue === 1
  || String(
    rawLockValue ?? ''
  )
    .trim()
    .toLowerCase() === 'true'
  || String(
    rawLockValue ?? ''
  )
    .trim() === '1';

return [
  {
    json: {
      ...input,

      lock_acquired_raw:
        rawLockValue ?? null,

      lock_acquired_boolean:
        lockAcquired,

      lock_acquired_flag:
        lockAcquired
          ? 1
          : 0,

      lock_route:
        lockAcquired
          ? 'LOCK_ACQUIRED'
          : 'LOCK_NOT_ACQUIRED',

      workflow_code:
        'WF-019',

      normalized_at:
        new Date().toISOString(),
    },
  },
];
